#pragma once
#include "worlded/world.hpp"
#include "playtest.hpp"
#include <QtCore>
namespace worlded {
inline std::string reference_hash(const Bytes& bytes){return QCryptographicHash::hash(QByteArray(reinterpret_cast<const char*>(bytes.data()),int(bytes.size())),QCryptographicHash::Sha256).toHex().toStdString();}
inline bool reference_mobile(const GameObject& object){return object.type==2 || (object.type>=4 && object.type<=16) || (object.number("FLAGS")&0x2000);}
inline void capture_reference_prototype(SceneReference& ref,const Installation& installation,unsigned id){for(const auto& [path,sources]:installation.resources())if(path.rfind("proto/",0)==0 && QString::fromStdString(path).endsWith(".pro") && QRegularExpression("^proto/(\\d+)").match(QString::fromStdString(path)).captured(1).toUInt()==id){if(!ref.resources.count(path))ref.resources[path]=installation.read(path);return;}/* Missing prototypes remain visible in the editor; update review rejects the incomplete reference. */}
inline void capture_scene_reference(Building& building,const Installation& installation,const std::string& source,bool generated){
    if(building.reference)throw std::runtime_error("A captured reference cannot be replaced implicitly");auto ref=std::make_shared<SceneReference>();ref->id=QUuid::createUuid().toString(QUuid::Id128).toStdString();ref->map=building.map_name;ref->sector=building.sector_id;ref->source_path=source;ref->generated=generated;auto raw=installation.read(source);ref->source_hash=reference_hash(raw);ref->ground=building.ground.encode();ref->resources[source]=raw;
    std::vector<std::string> dependencies{"maps/"+building.map_name+"/map.prp"};if(generated){dependencies.push_back("maps/"+building.map_name+"/terrain.tdf");dependencies.push_back("terrain/terrain.mes");}for(const auto& path:dependencies)if(installation.contains(path))ref->resources[path]=installation.read(path);
    for(unsigned i=0;i<building.objects.size();i++){auto& object=building.objects[i];if(object.editor_id.empty())object.editor_id=clone_instance(object).id;ref->origins.push_back({object.editor_id,source,ref->source_hash,i,reference_mobile(object),object});capture_reference_prototype(*ref,installation,object.prototype_id);}building.reference=ref;
}
inline void validate_scene_reference(const SceneReference& ref){auto source=ref.resources.find(ref.source_path);if(source==ref.resources.end() || reference_hash(source->second)!=ref.source_hash)throw std::runtime_error("Reference source digest does not match its stored bytes");std::set<std::string> keys;for(const auto& origin:ref.origins)if(origin.editor_id.empty() || !keys.insert(origin.editor_id).second)throw std::runtime_error("Reference origin identities are ambiguous");}
inline QStringList reference_drift(const SceneReference& ref,const Installation& installation){QStringList result;for(const auto& [path,bytes]:ref.resources)if(!installation.contains(path) || reference_hash(installation.read(path))!=reference_hash(bytes))result<<QString::fromStdString(path);return result;}
struct ReferenceMobile {GameObject object;std::string source,hash;};
inline std::vector<ReferenceMobile> reference_mobiles(const Installation& installation,const Building& building){std::map<std::string,ReferenceMobile> byId;auto add=[&](const std::string& path,std::size_t offset){auto raw=installation.read(path);auto hash=reference_hash(raw);for(auto object:read_objects(raw,offset)){if(object.id.substr(0,4)!="0200")continue;auto loc=object.number("LOCATION");if((std::uint32_t(loc)>>6)!=(building.sector_id&0x3ffffff) || (loc>>38)!=(building.sector_id>>26) || (object.number("FLAGS")&0x1000))continue;set_number(object,"LOCATION",(loc&63)|(((loc>>32)&63)<<32));transform_npc_routes(object,building.sector_id,false);byId[object.id]={std::move(object),path,hash};}};
    auto bundle=mobile_bundle_name(building.map_name);if(installation.contains(bundle))add(bundle,16);auto prefix="maps/"+building.map_name+"/";for(const auto& [path,sources]:installation.resources())if(path.rfind(prefix,0)==0 && QString::fromStdString(path).endsWith(".mob"))add(path,0);std::vector<ReferenceMobile> result;for(auto& [id,mobile]:byId)if(std::none_of(building.objects.begin(),building.objects.end(),[&](const auto& object){return object.id==id;}))result.push_back(std::move(mobile));return result;
}
inline void import_reference_mobile(Building& building,const Installation& installation,ReferenceMobile mobile){if(!building.reference)throw std::runtime_error("Capture or adopt the original reference before importing campaign objects");if(mobile.object.id.substr(0,4)!="0200")throw std::runtime_error("Campaign object has no persistent GUID");for(const auto& object:building.objects)if(object.id==mobile.object.id)throw std::runtime_error("This object is already in the project");mobile.object.editor_id=clone_instance(mobile.object).id;auto ref=std::make_shared<SceneReference>(*building.reference);ref->origins.push_back({mobile.object.editor_id,mobile.source,mobile.hash,0,true,mobile.object});capture_reference_prototype(*ref,installation,mobile.object.prototype_id);building.reference=ref;building.objects.push_back(std::move(mobile.object));}
// Legacy adoption never guesses by position. Existing objects must match a unique
// persistent GUID or their exact original serialized record, ignoring selection ID.
inline void adopt_scene_reference(Building& building,const Installation& installation){if(building.reference)throw std::runtime_error("This project already has an original reference");auto source=read_world_sector(installation,building.map_name,unsigned(building.sector_id&0x3ffffff),unsigned(building.sector_id>>26));Building baseline{BuildingPlan{},source.sector,sector_objects(source.sector),{}};baseline.map_name=building.map_name;baseline.sector_id=building.sector_id;baseline.existing_map=true;
    for(auto& original:baseline.objects){auto loc=original.number("LOCATION");set_number(original,"LOCATION",(loc&63)|(((loc>>32)&63)<<32));transform_npc_routes(original,building.sector_id,false);std::vector<GameObject*> candidates;for(auto& edited:building.objects)if((original.id.substr(0,4)=="0200" && original.id==edited.id) || encode_instance(original)==encode_instance(edited))candidates.push_back(&edited);if(candidates.size()>1)throw std::runtime_error("Ambiguous original object; legacy reference adoption refused");original.editor_id=candidates.empty()?clone_instance(original).id:candidates[0]->editor_id;}
    capture_scene_reference(baseline,installation,source.source,source.generated);for(const auto& edited:building.objects){bool matched=false;for(const auto& origin:baseline.reference->origins)if(origin.editor_id==edited.editor_id)matched=true;if(!matched && edited.id.substr(0,4)!="0200")throw std::runtime_error("An edited original object has no reliable identity; restore it before adopting a reference");}auto adopted=std::make_shared<SceneReference>(*baseline.reference);auto mobiles=reference_mobiles(installation,baseline);for(const auto& edited:building.objects){bool known=std::any_of(adopted->origins.begin(),adopted->origins.end(),[&](const auto& origin){return origin.editor_id==edited.editor_id;});if(known)continue;for(const auto& mobile:mobiles)if(mobile.object.id==edited.id){auto original=mobile.object;original.editor_id=edited.editor_id;adopted->origins.push_back({edited.editor_id,mobile.source,mobile.hash,0,true,original});capture_reference_prototype(*adopted,installation,original.prototype_id);break;}}building.reference=adopted;
}
}
